/* Hollow Signal — standalone interface prototype; all data and interactions are local to this page. */
(() => {
'use strict';
const art = '../../art/';
const ui = name => art+'ui/'+name+'.svg';
const monster = name => art+'next/starters/'+name+'.png';
const robot = name => art+'robots/'+name+'.png';
const state={screen:'field',previous:'field',coins:2480,steps:0,party:0,filter:'All',guide:'Billies',zone:'Clovercrest',bag:{'Tonic':4,'Spark Soda':2,'Tax Stamp':7,'Biscuit':3},done:false,battle:null,reduced:false,sound:true,glass:true,quest:false,energy:92,seen:[]};
const party=[{name:'Billgoat',type:'Billie · Verdant',level:12,hp:87,max:100,img:monster('billgoat'),desc:'A particularly ambitious pasture-dweller.'},{name:'Everyotter',type:'Billie · Current',level:10,hp:64,max:80,img:monster('everyotter'),desc:'Always ready to optimize a river.'},{name:'Bulwark',type:'Robot · Ember',level:9,hp:76,max:90,img:robot('bulwark'),desc:'An earnest little machine with a very large shield.'},{name:'Cartotter',type:'Billie · Tidal',level:7,hp:65,max:65,img:monster('cartotter'),desc:'A curious mapmaker from upstream.'}];
const items=[{name:'Tonic',description:'Restore 30 HP to one party member.',icon:'heart'},{name:'Spark Soda',description:'Restore 15 HP to one party member.',icon:'bolt'},{name:'Tax Stamp',description:'A collector’s favorite currency.',icon:'coin'},{name:'Biscuit',description:'A comforting treat from the ranch.',icon:'leaf'}];
const places=[{name:'Clovercrest',sub:'Starting town · Meadow District',img:'clovercrest.webp'},{name:'Marigold',sub:'Sunlit terraces · South',img:'marigold.webp'},{name:'Copperleaf',sub:'Industrial quarter · East',img:'copperleaf.webp'},{name:'Kelpport',sub:'Waterfront · West',img:'kelpport.webp'},{name:'Lanternhall',sub:'The old city · North',img:'lanternhall.webp'}];
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function current(){return party[state.party]}
function toast(s){$('toasts').innerHTML='<div class="toast">'+esc(s)+'</div>';clearTimeout(toast.timer);toast.timer=setTimeout(()=>{$('toasts').innerHTML=''},2800)}
function go(screen){state.screen=screen;closeModal(false);render();$('view').scrollTop=0}
function modal(title,body){$('modal-root').innerHTML='<section class="modal" role="dialog" aria-modal="true" aria-label="'+esc(title)+'"><div class="modal-head"><h3>'+esc(title)+'</h3><button class="secondary" data-action="close" aria-label="Close">×</button></div>'+body+'</section>'}
function closeModal(focus=true){$('modal-root').innerHTML='';if(focus)$('view').focus()}
function button(text,action,arg='',cls='primary'){return '<button class="'+cls+'" data-action="'+action+'" data-value="'+esc(arg)+'">'+text+'</button>'}
function card(p,idx){return '<button class="list-card" data-action="details" data-value="'+idx+'"><img class="row-image" src="'+p.img+'" alt=""><span style="flex:1"><b>'+p.name+'</b><small>'+p.type+' · LV '+p.level+'</small><span class="hp"><span style="width:'+Math.round(p.hp/p.max*100)+'%"></span></span><small>'+p.hp+' / '+p.max+' HP</small></span><span class="arrow">›</span></button>'}
function viewField(){return '<div class="screen-intro"><div><div class="kicker">THE HOLLOW EARTH / SECTOR 01</div><h2>Out & about.</h2></div><span class="mini-tag">✦ DAY 07</span></div><div class="world-hero"><div class="hero-top"><span class="glass-pill">☀ Inner Sun</span><span class="glass-pill">23° · Clear</span></div><img class="art-person" src="'+art+'people/boy_front.png" alt="Explorer sprite"><div class="hero-bottom"><div><small>YOU ARE HERE</small><strong>'+esc(state.zone)+'</strong><small>'+state.steps+' exploration moves · demo</small></div><button class="joystick" data-action="walk" aria-label="Move in the prototype"><span>✛</span></button></div></div><div class="section-head"><b>Your expedition</b><span>QUICK ACTIONS ↘</span></div><div class="action-grid"><button class="action-card" data-screen="map"><img src="'+ui('map')+'" alt=""><b>World map</b><small>See what’s beyond</small></button><button class="action-card" data-screen="battle"><img src="'+ui('fight')+'" alt=""><b>Test battle</b><small>Ready your team</small></button><button class="action-card" data-screen="team"><img src="'+ui('team')+'" alt=""><b>My crew</b><small>'+party.length+' companions</small></button><button class="action-card" data-screen="bag"><img src="'+ui('bag')+'" alt=""><b>Field bag</b><small>Everything you carry</small></button></div><div class="section-head"><b>Field journal</b><span>01 / ACTIVE</span></div><button class="glass-card field-quest full" data-action="quest"><span class="star">'+(state.quest?'✓':'✦')+'</span><span><b>'+ (state.quest?'Job well done!':'The curious signal')+'</b><small>'+(state.quest?'Claimed the demo reward':'Find the origin of the strange transmission')+'</small></span><span style="margin-left:auto">↗</span></button><div class="note-band">INTERFACE LAB · The landscape is an existing Pocket Billies postcard. Walking is a UI demonstration, not the real WebGL world.</div>'}
function viewTeam(){return '<div class="kicker">THE PEOPLE & CREATURES YOU KEEP</div><h2>The crew.</h2><div class="profile-card flex-row"><img src="'+current().img+'" alt=""><span><span class="micro" style="color:#3a6054">LEAD COMPANION</span><br><b>'+current().name+'</b><br><span class="muted" style="color:#486660">LV '+current().level+' · '+current().type+'</span></span></div><div class="section-head"><b>Companions</b><span>'+party.length+' / 6 ACTIVE</span></div>'+party.map(card).join('')+'<div class="note-band">Tap any companion to inspect it, heal it, or move it into the lead position.</div>'}
function viewBag(){const list=items.filter(x=>state.filter==='All'||(state.filter==='Medicine'&&['Tonic','Spark Soda'].includes(x.name))||(state.filter==='Other'&&!['Tonic','Spark Soda'].includes(x.name)));return '<div class="kicker">NEVER LEAVE THE RANCH EMPTY-HANDED</div><h2>Field bag.</h2><div class="glass-card flex-row space-between"><div><span class="micro">POCKET CAPACITY</span><h3 style="margin:5px 0">'+Object.values(state.bag).reduce((a,b)=>a+b,0)+' objects</h3></div><span style="font-size:37px">✦</span></div><div class="section-head"><b>Packed essentials</b><span>INVENTORY</span></div><div class="tabs">'+['All','Medicine','Other'].map(t=>'<button class="'+(state.filter===t?'selected':'')+'" data-action="filter" data-value="'+t+'">'+t+'</button>').join('')+'</div><div class="item-grid">'+list.map(item=>'<button class="item-card" data-action="item" data-value="'+item.name+'"><span class="qty">×'+state.bag[item.name]+'</span><img src="'+ui(item.icon)+'" alt=""><b>'+item.name+'</b><small>'+item.description+'</small></button>').join('')+'</div><div class="note-band">Items are mock data. Using a Tonic or Spark Soda updates the companion’s HP locally.</div>'}
function viewMap(){return '<div class="kicker">A WORLD INSIDE A WORLD</div><h2>Find your way.</h2><div class="region" aria-label="Stylized region overview"><span class="map-pin current" style="top:48%;left:33%">⌖</span><span class="map-pin" style="top:26%;left:64%">✦</span><span class="map-pin" style="top:66%;left:71%">◈</span></div><p class="map-label">An illustrated route selector inspired by the game’s bowl-shaped world. This is not the actual 3D map.</p><div class="section-head"><b>Destinations</b><span>5 / LOCATIONS</span></div>'+places.map((p,i)=>'<button class="list-card" data-action="place" data-value="'+i+'"><img class="row-image" src="'+art+'postcards/'+p.img+'" alt=""><span style="flex:1"><b>'+p.name+'</b><small>'+p.sub+'</small></span><span class="arrow">'+(state.zone===p.name?'✓':'↗')+'</span></button>').join('')}
function viewGuide(){const data=state.guide==='Billies'?party.filter(p=>p.type.startsWith('Billie')):party.filter(p=>p.type.startsWith('Robot'));return '<div class="kicker">ODD THINGS / FIELD RECORDS / 01</div><h2>The field guide.</h2><div class="tabs">'+['Billies','Robots'].map(t=>'<button class="'+(state.guide===t?'selected':'')+'" data-action="guideTab" data-value="'+t+'">'+t+'</button>').join('')+'</div><div class="solid-card pattern-bg"><div class="micro" style="color:#3e635b">CURIOUS CREATURES</div><h3 style="font-size:26px;margin-top:8px">'+(state.guide==='Billies'?'Meet the Billies.':'Built differently.')+'</h3><p style="font-size:12px;line-height:1.6">'+(state.guide==='Billies'?'A catalog of the most improbably entrepreneurial wildlife in the Hollow Earth.':'Meet the robots: soulful machines assembled from curious parts.')+'</p></div>'+data.map((p)=>card(p,party.indexOf(p))).join('')+'<div class="note-band">Entries shown here are representative demo content, not a complete game database.</div>'}
function newBattle(){state.battle={enemy:64,max:64,ally:Math.max(current().hp,1),maxAlly:current().max,turn:1,log:'A wild Boostox wants to negotiate!',ended:false,won:false}}
function viewBattle(){if(!state.battle)newBattle();const b=state.battle;return '<div class="kicker">ENCOUNTER / LIVE UI DEMONSTRATION</div><div class="screen-intro"><h2>'+ (b.ended?(b.won?'Victory!':'Battle over.'):'Your move!')+'</h2><span class="mini-tag">TURN '+b.turn+'</span></div><div class="battle-stage"><div class="enemy-name">BOOSTOX · LV 10</div><img class="battle-unit enemy" src="'+monster('boostox')+'" alt="Boostox"><img class="battle-unit player" src="'+current().img+'" alt="'+current().name+'"></div><div class="battle-status"><div><span class="micro">YOUR LEAD</span><strong style="display:block">'+current().name+'</strong><small>LV '+current().level+'</small></div><div class="health-box"><span class="micro">HP '+b.ally+' / '+b.maxAlly+'</span><div class="hp"><span style="width:'+100*b.ally/b.maxAlly+'%"></span></div></div></div><div class="glass-card"><div class="flex-row space-between"><b style="font:700 17px Pixel">Boostox</b><span class="micro">HP '+b.enemy+' / '+b.max+'</span></div><div class="hp"><span style="width:'+100*b.enemy/b.max+'%"></span></div></div><div class="battle-log" aria-live="polite">'+esc(b.log)+'</div>'+(b.ended?button('↺ NEW ENCOUNTER','newBattle','','primary full')+' '+button('Back to the field','nav','field','secondary full'):'<div class="battle-command"><button data-action="attack" data-value="Tax Strike">✶ Tax Strike</button><button data-action="attack" data-value="Market Rush">↗ Market Rush</button><button data-action="battleBag">✚ Field bag</button><button data-action="battleSwitch">⇄ Switch</button></div>'+button('Leave encounter','retreat','','secondary full'))}
function viewProfile(){return '<div class="kicker">AN EXPLORER’S PAPER TRAIL</div><h2>Your dossier.</h2><div class="profile-card flex-row"><img src="'+art+'people/boy_front.png" alt="Player sprite"><div><b>Explorer 07</b><br><small>Independent field researcher</small><br><small>Based in '+esc(state.zone)+'</small></div></div><div class="section-head"><b>Expedition stats</b><span>LOCAL DEMO</span></div><div class="glass-card"><div class="setting-row"><b>Companions</b><strong>'+party.length+'</strong></div><div class="setting-row"><b>Coin balance</b><strong>'+state.coins+'</strong></div><div class="setting-row"><b>Exploration moves</b><strong>'+state.steps+'</strong></div><div class="setting-row"><b>Current region</b><strong>'+state.zone+'</strong></div></div>'+button('Interface settings','nav','settings','primary full')+'<div class="note-band">No login, account connection, save import, or game data mutation occurs in this prototype.</div>'}
function viewSettings(){return '<div class="kicker">MAKE THE INTERFACE YOURS</div><h2>Tune the signal.</h2><div class="glass-card"><h3>Presentation</h3>'+setting('glass','Frosted glass','Blurred overlays and tactile depth')+setting('reduced','Reduced motion','Keep animations low-key')+setting('sound','Feedback cues','Show simulated feedback notifications')+'</div><div class="solid-card"><h3>Prototype controls</h3><p style="font-size:12px;line-height:1.6">Reset the demo’s items, HP, wallet, location, and battle progress.</p>'+button('Reset demo progress','reset','','primary full')+'</div><div class="note-band">The glass switch changes translucency throughout the prototype; reduced motion disables interface animations. No device sound is played.</div>'}
function setting(key,title,subtitle){const on=state[key];return '<div class="setting-row"><span><b>'+title+'</b><br><small>'+subtitle+'</small></span><button class="toggle '+(on?'on':'')+'" role="switch" aria-checked="'+on+'" data-action="setting" data-value="'+key+'">'+(on?'ON':'OFF')+'</button></div>'}
const screens={field:viewField,team:viewTeam,bag:viewBag,map:viewMap,guide:viewGuide,battle:viewBattle,profile:viewProfile,settings:viewSettings};
const nav=[['field','house','Field'],['team','team','Crew'],['bag','bag','Bag'],['map','map','World'],['guide','ledger','Guide']];
function render(){document.documentElement.style.setProperty('--glass',state.glass?'rgba(20,46,47,.64)':'rgba(20,46,47,.97)');document.documentElement.style.scrollBehavior=state.reduced?'auto':'';$('device').classList.toggle('reduce',state.reduced);$('topbar').innerHTML='<div class="identity"><img src="'+art+'people/boy_front.png" alt=""><span><strong>EXPLORER 07</strong><small>LV 12 · '+esc(state.zone)+'</small></span></div><span class="wallet"><img src="'+art+'coins/gold_16.png" alt="">'+state.coins.toLocaleString()+'</span><button class="icon-button" aria-label="Profile and settings" data-screen="profile">☰</button>';$('dock').innerHTML=nav.map(([id,icon,label])=>'<button data-screen="'+id+'" class="'+(state.screen===id?'active':'')+'" '+(state.screen===id?'aria-current="page"':'')+'><img src="'+ui(icon)+'" alt="">'+label+'</button>').join('');$('view').innerHTML=(screens[state.screen]||viewField)();$('view').setAttribute('aria-label',state.screen+' screen')}
function details(i){const p=party[i];if(!p)return;modal(p.name,'<img class="modal-art" src="'+p.img+'" alt=""><p class="muted">'+p.type+' · LEVEL '+p.level+'</p><p>'+p.desc+'</p><div class="hp"><span style="width:'+(p.hp/p.max*100)+'%"></span></div><p>'+p.hp+' / '+p.max+' HP</p><div class="flex-col">'+button(state.party===i?'Currently in the lead':'Make lead companion','lead',i,'primary full')+button('Use a Tonic ('+state.bag.Tonic+' left)','heal',i,'secondary full')+'</div>')}
function item(name){const it=items.find(x=>x.name===name);if(!it)return;modal(name,'<img class="modal-art" src="'+ui(it.icon)+'" alt=""><p>'+it.description+'</p><p class="muted">In bag: '+state.bag[name]+'</p>'+(name==='Tonic'||name==='Spark Soda'?button('Use on lead companion','useItem',name,'primary full'):button('Keep in bag','close','','primary full')))}
function battleTurn(move){let b=state.battle;if(!b||b.ended)return;const damage=move==='Tax Strike'?19:27;b.enemy=Math.max(0,b.enemy-damage);b.log=current().name+' used '+move+'! '+damage+' damage.';if(b.enemy===0){b.ended=true;b.won=true;state.coins+=95;b.log+=' Boostox retreated. You found 95 coins!';}else{const hit=11;b.ally=Math.max(0,b.ally-hit);current().hp=b.ally;b.turn++;b.log+=' Boostox countered for '+hit+' HP.';if(b.ally===0){b.ended=true;b.log+=' Your companion fainted.';}}render()}
function handle(action,v){switch(action){case 'nav':go(v);break;case 'close':closeModal();break;case 'walk':state.steps++;if(state.steps%3===0)toast('A curious rustle from the tall grass…');render();break;case 'details':details(Number(v));break;case 'lead':state.party=Number(v);closeModal();render();toast(current().name+' is now your lead!');break;case 'heal':heal('Tonic',Number(v));break;case 'filter':state.filter=v;render();break;case 'item':item(v);break;case 'useItem':heal(v,state.party);break;case 'quest':if(!state.quest){state.quest=true;state.coins+=120;toast('Journal updated! +120 coins')}else toast('This demo quest is complete.');render();break;case 'place':{let p=places[Number(v)];if(p)modal(p.name,'<img src="'+art+'postcards/'+p.img+'" style="width:100%;border-radius:20px 5px 20px 5px" alt=""><p>'+p.sub+'</p><p class="muted">Select travel to change the sample location in this prototype.</p>'+button('Travel here','travel',p.name,'primary full'));break;}case 'travel':state.zone=v;closeModal();go('field');toast('Arrived at '+v+'!');break;case 'guideTab':state.guide=v;render();break;case 'newBattle':newBattle();render();break;case 'attack':battleTurn(v);break;case 'retreat':go('field');toast('You left the encounter.');break;case 'battleBag':modal('Battle supplies',items.filter(x=>['Tonic','Spark Soda'].includes(x.name)).map(x=>button(x.name+' ×'+state.bag[x.name],'battleHeal',x.name,'secondary full')).join('<br>'));break;case 'battleHeal':if(heal(v,state.party,true)){state.battle.ally=current().hp;state.battle.log=current().name+' recovered health!';render()}break;case 'battleSwitch':modal('Switch companion',party.map((p,i)=>button(p.name+' · '+p.hp+' HP','battleLead',i,'secondary full')).join('<br>'));break;case 'battleLead':state.party=Number(v);state.battle.ally=current().hp;state.battle.maxAlly=current().max;state.battle.log=current().name+' entered the encounter!';closeModal();render();break;case 'setting':state[v]=!state[v];render();toast('Setting updated: '+v);break;case 'reset':state.coins=2480;state.steps=0;state.party=0;state.zone='Clovercrest';state.quest=false;state.bag={'Tonic':4,'Spark Soda':2,'Tax Stamp':7,'Biscuit':3};party.forEach((p,i)=>p.hp=[87,64,76,65][i]);state.battle=null;go('field');toast('Demo progress reset.');break;default:toast('Interactive sample, more screens coming soon.');}}
function heal(name,i,battle=false){if(!state.bag[name]){toast('None left in your bag.');return false}const p=party[i],amount=name==='Tonic'?30:15;if(p.hp>=p.max){toast(p.name+' is already at full HP.');return false}p.hp=Math.min(p.max,p.hp+amount);state.bag[name]--;closeModal();if(!battle)render();toast(p.name+' recovered '+amount+' HP (up to maximum).');return true}
document.addEventListener('click',e=>{if(e.target.closest('[data-screen]')){go(e.target.closest('[data-screen]').dataset.screen);return}const b=e.target.closest('[data-action]');if(b)handle(b.dataset.action,b.dataset.value||'');else if(e.target===$('modal-root'))closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('modal-root').children.length)closeModal();if(e.key==='ArrowUp'&&state.screen==='field'){state.steps++;render();toast('Exploration move '+state.steps)}});render();
})();